import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [first, second] = input;
const [n, k] = first.split(" ").map(Number);
const a = second.split(" ").map(Number);

// 両端キュー（添字を持つ）。中の値は先頭から単調減少に保つ
const deque = new Int32Array(n);
let head = 0;
let tail = 0;
const out: number[] = [];
for (let i = 0; i < n; i++) {
  // 新しい値以下の要素は、今後最大値になることはない
  while (tail > head && a[deque[tail - 1]] <= a[i]) tail--;
  deque[tail++] = i;
  // 窓から外れた先頭を捨てる
  if (deque[head] <= i - k) head++;
  if (i >= k - 1) out.push(a[deque[head]]);
}
console.log(out.join(" "));
